<?php defined('AFAQ') || exit;
$sub = trim(substr((string)parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH), strlen('/admin')), '/'); $seg = explode('/', $sub); $page = $seg[0] ?: 'home'; $arg = $seg[1] ?? '';
$post = $_SERVER['REQUEST_METHOD'] === 'POST'; header('Cache-Control: no-store'); header('X-Robots-Tag: noindex, nofollow');
function adm($title, $body) { $S = settings(); $f = flash(); $nav = ['' => 'Dashboard', 'settings' => 'Site settings', 'services' => 'Services', 'projects' => 'Projects', 'presets' => 'Calculator presets', 'inquiries' => 'Inquiries'];
  echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>' . h($title) . ' | Admin</title><link rel="stylesheet" href="/assets/site.css?v=' . @filemtime(ROOT . '/assets/site.css') . '"><style>:root{--color-primary:' . h($S['color_primary']) . ';--color-bg:' . h($S['color_bg']) . ';--color-secondary:' . h($S['color_secondary']) . '}.adm{display:flex;gap:.25rem;flex-wrap:wrap}.adm a{padding:.6rem .8rem;min-height:44px;display:inline-flex;align-items:center;text-decoration:none;color:var(--muted);font-size:.9rem}.adm a:hover,.adm a.on{color:var(--stone)}.adm a.on{border-bottom:2px solid var(--color-primary)}table{width:100%;border-collapse:collapse}td,th{padding:.75rem;border-bottom:1px solid var(--border);text-align:left;vertical-align:middle}.thumb{width:72px;height:54px;object-fit:cover;border:1px solid var(--border)}.row-actions{display:flex;gap:.5rem;flex-wrap:wrap}.tw{overflow-x:auto}</style></head><body><header class="site-header"><div class="container header-row"><nav class="adm" aria-label="Admin">';
  foreach ($nav as $k => $l) echo '<a href="/admin' . ($k ? '/' . $k : '') . '"' . ((isset($GLOBALS['page']) && (($GLOBALS['page'] === 'home' ? '' : $GLOBALS['page']) === $k)) ? ' class="on"' : '') . '>' . h($l) . '</a>';
  echo '<a href="/" target="_blank">View site</a></nav><form method="post" action="/admin/logout">' . csrf() . '<button class="btn btn-ghost" type="submit">Sign out</button></form></div></header><main class="container section stack gap8"><h1 class="h1">' . h($title) . '</h1>';
  if ($f) echo '<p role="' . ($f[1] ? 'status' : 'alert') . '" class="' . ($f[1] ? 'form-ok' : 'form-error') . '">' . h($f[0]) . '</p>'; echo $body . '</main></body></html>'; }
function plain($title, $body) { $S = settings(); $f = flash(); echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>' . h($title) . '</title><link rel="stylesheet" href="/assets/site.css"></head><body><main class="container section"><div class="panel stack" style="max-width:520px;margin:auto"><h1 class="h2">' . h($title) . '</h1>' . ($f ? '<p role="alert" class="' . ($f[1] ? 'form-ok' : 'form-error') . '">' . h($f[0]) . '</p>' : '') . $body . '</div></main></body></html>'; }
function inp($n, $l, $v = '', $t = 'text', $x = '') { return '<label class="field"><span>' . h($l) . '</span><input name="' . h($n) . '" type="' . $t . '" value="' . h($v) . '" ' . $x . '></label>'; }
function area($n, $l, $v, $r = 4) { return '<label class="field"><span>' . h($l) . '</span><textarea name="' . h($n) . '" rows="' . $r . '">' . h($v) . '</textarea></label>'; }
function chk($n, $l, $on) { return '<label class="check"><input type="checkbox" name="' . h($n) . '"' . ($on ? ' checked' : '') . '><span>' . h($l) . '</span></label>'; }
function img_field($n, $l, $cur) { return '<div class="field"><span>' . h($l) . ' <small class="caption">(JPG, PNG or WebP, max 5 MB)</small></span>' . ($cur ? '<img class="thumb" src="' . h(img($cur)) . '" alt=""><label class="check"><input type="checkbox" name="rm_' . h($n) . '"><span>Remove current image</span></label>' : '') . '<input type="file" name="' . h($n) . '" accept="image/jpeg,image/png,image/webp"></div>'; }
function guard() { if (!csrf_ok()) { flash('Your session expired. Please try again.', false); redirect($_SERVER['REQUEST_URI']); } }
/** Handles one image field: returns the new stored name, keeps the old one, or clears it. Sets $errs on failure. */
function take_image($field, $old, &$errs, $file = null) { $f = $file ?? ($_FILES[$field] ?? null); [$ok, $v] = upload_image($f); if ($ok === false) { $errs[] = $v; return $old; } if ($ok === true) { delete_upload($old); return $v; } if (!empty($_POST['rm_' . $field])) { delete_upload($old); return ''; } return $old; }

// ---- auth
$admins = (int)q('SELECT COUNT(*) FROM admins')->fetchColumn();
if ($page === 'setup' || ($admins === 0 && $page !== 'logout')) {
  if ($admins > 0) redirect('/admin/login');
  if ($post) { guard(); $em = strtolower(trim($_POST['email'] ?? '')); $pw = (string)($_POST['password'] ?? ''); $err = '';
    if (!rate_limit('setup:' . ip(), 10, 900)) $err = 'Too many attempts. Try again later.'; elseif (!hash_equals(SETUP_CODE, trim($_POST['code'] ?? ''))) $err = 'The setup code is not correct.'; elseif (!filter_var($em, FILTER_VALIDATE_EMAIL)) $err = 'Enter a valid email address.'; elseif (strlen($pw) < 10) $err = 'The password must be at least 10 characters.';
    if (!$err) { q('INSERT INTO admins(email,pass,created) VALUES(?,?,?)', [$em, password_hash($pw, PASSWORD_DEFAULT), date('c')]); session_regenerate_id(true); $_SESSION['admin'] = (int)db()->lastInsertId(); flash('Admin account created. Welcome!'); redirect('/admin'); }
    flash($err, false); redirect('/admin/setup'); }
  plain('Create your admin account', '<p class="muted small">This page is only available until the first admin is created.</p><form method="post" class="stack gap4">' . csrf() . inp('email', 'Email', '', 'email', 'required autocomplete="username"') . inp('password', 'Password (at least 10 characters)', '', 'password', 'required autocomplete="new-password"') . inp('code', 'Setup code (from your instructions)', '', 'text', 'required autocomplete="off"') . '<button class="btn btn-primary" type="submit">Create account</button></form>'); return; }
if ($page === 'login') {
  if (!empty($_SESSION['admin'])) redirect('/admin');
  if ($post) { guard(); $em = strtolower(trim($_POST['email'] ?? '')); $ok = false;
    if (!rate_limit('login:' . ip(), 8, 900)) { flash('Too many attempts. Try again in 15 minutes.', false); redirect('/admin/login'); }
    $a = row('SELECT * FROM admins WHERE email=?', [$em]); $ok = password_verify((string)($_POST['password'] ?? ''), $a ? $a['pass'] : '$2y$10$abcdefghijklmnopqrstuuAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA'); // same work either way
    if ($a && $ok) { session_regenerate_id(true); $_SESSION['admin'] = (int)$a['id']; redirect('/admin'); } flash('Incorrect email or password.', false); redirect('/admin/login'); }
  plain('Admin sign in', '<form method="post" class="stack gap4">' . csrf() . inp('email', 'Email', '', 'email', 'required autocomplete="username"') . inp('password', 'Password', '', 'password', 'required autocomplete="current-password"') . '<button class="btn btn-primary" type="submit">Sign in</button></form>'); return; }
if ($page === 'logout') { if ($post && csrf_ok()) { $_SESSION = []; session_destroy(); } redirect('/admin/login'); }
if (empty($_SESSION['admin']) || !row('SELECT id FROM admins WHERE id=?', [$_SESSION['admin']])) redirect('/admin/login');

// ---- entity definitions
$ENT = [
 'services' => ['Services', 'services', 'name', true, [['name', 'Name', 'text'], ['summary', 'Short summary', 'area2'], ['content', 'Full description (blank line between paragraphs)', 'area8'], ['features', 'Features (one per line)', 'area5'], ['image', 'Image', 'img'], ['sort', 'Order (lower shows first)', 'number'], ['published', 'Published (visible on the website)', 'check']]],
 'projects' => ['Projects', 'projects', 'name', true, [['name', 'Project name', 'text'], ['category', 'Category', 'text'], ['location', 'Location', 'text'], ['client', 'Client', 'text'], ['status', 'Status', 'status'], ['start_date', 'Start date', 'date'], ['end_date', 'Completion date', 'date'], ['description', 'Description (blank line between paragraphs)', 'area6'], ['scope', 'Scope of work', 'area4'], ['video', 'Video link (optional, https://…)', 'url'], ['image', 'Main image', 'img'], ['gallery', 'Gallery images', 'gallery'], ['featured', 'Featured (shown first, larger)', 'check'], ['published', 'Published (visible on the website)', 'check'], ['sort', 'Order (lower shows first)', 'number']]],
 'presets' => ['Calculator presets', 'presets', 'name', false, [['kind', 'Type', 'kind'], ['name', 'Name', 'text'], ['length_mm', 'Length (mm)', 'mm'], ['width_mm', 'Width (mm)', 'mm'], ['height_mm', 'Height (mm)', 'mm'], ['joint_mm', 'Mortar joint (mm)', 'joint'], ['source', 'Source / note (maker, region)', 'text'], ['active', 'Active (shown in the calculator)', 'check'], ['sort', 'Order (lower shows first)', 'number']]],
];
function entity_form($key, $d, $id, $errs = []) { global $ENT; $f = ''; $b = '<form method="post" enctype="multipart/form-data" class="panel stack gap4" style="max-width:900px">' . csrf();
  foreach ($errs as $e) $b .= '<p role="alert" class="form-error">' . h($e) . '</p>';
  foreach ($ENT[$key][4] as [$n, $l, $t]) { $v = $d[$n] ?? ''; switch ($t) {
    case 'text': $b .= inp($n, $l, $v); break; case 'url': $b .= inp($n, $l, $v, 'url'); break; case 'date': $b .= inp($n, $l, $v, 'date'); break;
    case 'number': $b .= inp($n, $l, $v === '' ? 0 : $v, 'number', 'min="0" max="999"'); break; case 'mm': $b .= inp($n, $l, $v, 'number', 'step="any" min="0" required'); break; case 'joint': $b .= inp($n, $l, $v === '' ? 10 : $v, 'number', 'step="any" min="0" max="50"'); break;
    case 'check': $b .= chk($n, $l, $v === '' ? ($n === 'active') : (bool)$v); break; case 'img': $b .= img_field($n, $l, $v); break;
    case 'status': $b .= '<label class="field"><span>' . h($l) . '</span><select name="status">'; foreach (STATUSES as $k => $x) $b .= '<option value="' . $k . '"' . ((($v ?: 'COMPLETED') === $k) ? ' selected' : '') . '>' . $x . '</option>'; $b .= '</select></label>'; break;
    case 'kind': $b .= '<label class="field"><span>' . h($l) . '</span><select name="kind"><option value="brick"' . ($v === 'brick' ? ' selected' : '') . '>Brick</option><option value="block"' . ($v === 'block' ? ' selected' : '') . '>Block</option></select></label>'; break;
    case 'gallery': $g = json_decode($v ?: '[]', true) ?: []; $b .= '<div class="field"><span>' . h($l) . ' <small class="caption">(you can select several)</small></span>'; if ($g) { $b .= '<div class="row-actions">'; foreach ($g as $x) $b .= '<label class="check"><img class="thumb" src="' . h(img($x)) . '" alt=""><input type="checkbox" name="rm_gallery[]" value="' . h($x) . '"><span class="small">Remove</span></label>'; $b .= '</div>'; } $b .= '<input type="file" name="gallery_new[]" multiple accept="image/jpeg,image/png,image/webp"></div>'; break;
    default: $b .= area($n, $l, $v, (int)substr($t, 4)); } }
  return $b . '<div class="row-actions"><button class="btn btn-primary" type="submit">Save</button><a class="btn btn-ghost" href="/admin/' . $key . '">Cancel</a></div></form>'; }
function entity_collect($key, $old, &$errs) { global $ENT; $d = []; foreach ($ENT[$key][4] as [$n, $l, $t]) { $v = $_POST[$n] ?? ''; switch ($t) {
  case 'check': $d[$n] = isset($_POST[$n]) ? 1 : 0; break; case 'number': $d[$n] = max(0, min(999, (int)$v)); break; case 'img': $d[$n] = take_image($n, $old[$n] ?? '', $errs); break;
  case 'mm': $d[$n] = (float)$v; if (!($d[$n] > 0 && $d[$n] <= 2000)) $errs[] = $l . ' must be greater than 0.'; break; case 'joint': $d[$n] = (float)$v; if ($d[$n] < 0 || $d[$n] > 50) $errs[] = 'Mortar joint must be between 0 and 50 mm.'; break;
  case 'status': $d[$n] = isset(STATUSES[$v]) ? $v : 'COMPLETED'; break; case 'kind': $d[$n] = $v === 'block' ? 'block' : 'brick'; break;
  case 'date': $d[$n] = ($v !== '' && strtotime($v)) ? date('Y-m-d', strtotime($v)) : ''; break;
  case 'url': $v = trim($v); if ($v !== '' && !preg_match('#^https?://\S+$#i', $v)) $errs[] = 'The video link must start with http:// or https://'; $d[$n] = $v; break;
  case 'gallery': $g = json_decode($old[$n] ?? '[]', true) ?: []; foreach ((array)($_POST['rm_gallery'] ?? []) as $r) if (($i = array_search($r, $g, true)) !== false) { delete_upload($g[$i]); array_splice($g, $i, 1); }
    $fs = $_FILES['gallery_new'] ?? null; if ($fs && is_array($fs['name'])) foreach ($fs['name'] as $i => $_) { $one = ['name' => $fs['name'][$i], 'type' => $fs['type'][$i], 'tmp_name' => $fs['tmp_name'][$i], 'error' => $fs['error'][$i], 'size' => $fs['size'][$i]]; [$ok, $val] = upload_image($one); if ($ok === true) $g[] = $val; elseif ($ok === false) $errs[] = $val; }
    $d[$n] = json_encode(array_values($g)); break;
  default: $d[$n] = trim(mb_substr((string)$v, 0, $t === 'text' ? 160 : 8000)); } }
  if (isset($d['name']) && $d['name'] === '') $errs[] = 'Name is required.'; if (isset($d['summary']) && $d['summary'] === '') $errs[] = 'A short summary is required.';
  if (isset($d['start_date'], $d['end_date']) && $d['start_date'] && $d['end_date'] && $d['end_date'] < $d['start_date']) $errs[] = 'Completion date cannot be before the start date.'; return $d; }

if (isset($ENT[$page])) { [$ttl, $tbl, $lab, $slug, $fields] = $ENT[$page]; $key = $page;
  if ($arg === 'delete' && $post) { guard(); $r = row("SELECT * FROM $tbl WHERE id=?", [(int)($seg[2] ?? 0)]); if ($r) { foreach ($fields as [$n, , $t]) { if ($t === 'img') delete_upload($r[$n]); if ($t === 'gallery') foreach (json_decode($r[$n] ?: '[]', true) ?: [] as $g) delete_upload($g); } q("DELETE FROM $tbl WHERE id=?", [$r['id']]); flash('Deleted successfully.'); } redirect('/admin/' . $key); }
  if ($arg === 'new' || ctype_digit($arg)) { $id = (int)$arg; $old = $id ? row("SELECT * FROM $tbl WHERE id=?", [$id]) : []; if ($id && !$old) { flash('That item no longer exists.', false); redirect('/admin/' . $key); }
    $errs = []; $d = $old ?: [];
    if ($post) { guard(); $d = entity_collect($key, $old, $errs); if (!$errs) { try { if ($slug) $d['slug'] = unique_slug($tbl, $d['name'], $id);
        if ($id) { $set = implode(',', array_map(function ($c) { return "$c=?"; }, array_keys($d))); q("UPDATE $tbl SET $set WHERE id=?", array_merge(array_values($d), [$id])); }
        else { q("INSERT INTO $tbl(" . implode(',', array_keys($d)) . ') VALUES(' . implode(',', array_fill(0, count($d), '?')) . ')', array_values($d)); }
        flash('Saved successfully.'); redirect('/admin/' . $key); } catch (PDOException $e) { error_log($e->getMessage()); $errs[] = 'Could not save. Please try again.'; } } }
    adm(($id ? 'Edit ' : 'Add ') . strtolower($ttl === 'Calculator presets' ? 'preset' : rtrim($ttl, 's')), entity_form($key, $d, $id, $errs)); return; }
  $list = rows("SELECT * FROM $tbl ORDER BY " . ($key === 'presets' ? 'kind, sort, name' : 'sort, name'));
  $b = '<div><a class="btn btn-primary" href="/admin/' . $key . '/new">Add new</a></div>' . (!$list ? '<p class="notice small">Nothing here yet.</p>' : '<div class="tw"><table><tbody>');
  foreach ($list as $r) { $b .= '<tr><td>' . (isset($r['image']) && $r['image'] ? '<img class="thumb" src="' . h(img($r['image'])) . '" alt="">' : '') . '</td><td><strong>' . h($r['name']) . '</strong><br><span class="caption">' . h($key === 'presets' ? $r['kind'] . ' · ' . $r['length_mm'] . '×' . $r['width_mm'] . '×' . $r['height_mm'] . ' mm' . ($r['active'] ? '' : ' · inactive') : (($r['published'] ? 'Published' : 'Draft') . (!empty($r['featured']) ? ' · featured' : '') . ' · order ' . $r['sort'])) . '</span></td><td><div class="row-actions"><a class="btn btn-outline" href="/admin/' . $key . '/' . $r['id'] . '">Edit</a><form method="post" action="/admin/' . $key . '/delete/' . $r['id'] . '" onsubmit="return confirm(\'Delete this item? This cannot be undone.\')">' . csrf() . '<button class="btn btn-danger" type="submit">Delete</button></form></div></td></tr>'; }
  adm($ttl, $b . ($list ? '</tbody></table></div>' : '')); return; }

if ($page === 'inquiries') {
  if ($post) { guard(); $id = (int)($_POST['id'] ?? 0); if (($_POST['do'] ?? '') === 'delete') q('DELETE FROM inquiries WHERE id=?', [$id]); elseif (in_array($_POST['status'] ?? '', ['new', 'read', 'replied', 'archived'], true)) q('UPDATE inquiries SET status=? WHERE id=?', [$_POST['status'], $id]); flash('Updated.'); redirect('/admin/inquiries'); }
  $b = ''; $list = rows('SELECT * FROM inquiries ORDER BY id DESC LIMIT 200'); if (!$list) $b = '<p class="notice small">No messages yet.</p>';
  foreach ($list as $r) { $b .= '<div class="panel stack gap3"><div class="cta-row"><strong>' . h($r['name']) . '</strong><span class="caption">' . h(date('d M Y, H:i', strtotime($r['created']))) . '</span></div><span class="small muted">' . h(implode(' · ', array_filter([$r['phone'], $r['email']]))) . '</span><p style="margin:0;white-space:pre-wrap">' . h($r['message']) . '</p><form method="post" class="row-actions">' . csrf() . '<input type="hidden" name="id" value="' . $r['id'] . '"><select name="status" aria-label="Status" style="min-height:44px;background:var(--color-bg);color:var(--stone);border:1px solid var(--border)">'; foreach (['new', 'read', 'replied', 'archived'] as $s) $b .= '<option' . ($r['status'] === $s ? ' selected' : '') . '>' . $s . '</option>'; $b .= '</select><button class="btn btn-outline" type="submit">Update</button><button class="btn btn-danger" name="do" value="delete" type="submit" onclick="return confirm(\'Delete this message?\')">Delete</button></form></div>'; }
  adm('Inquiries', $b); return; }

if ($page === 'settings') { $S = settings(); $groups = [
  'Identity' => [['company', 'Company name'], ['brand', 'Brand name'], ['tagline', 'Tagline (small text under the brand)'], ['cta_text', 'Header button text']],
  'Homepage text' => [['hero_headline', 'Hero headline'], ['hero_sub', 'Hero supporting text', 'area'], ['description', 'Company description (replaces hero supporting text if filled)', 'area'], ['statement', 'Introduction statement'], ['intro', 'Introduction paragraph', 'area']],
  'Contact' => [['phone', 'Phone'], ['whatsapp', 'WhatsApp number (with country code)'], ['email', 'Email', 'email'], ['address', 'Address'], ['hours', 'Business hours'], ['maps', 'Google Maps link', 'url']],
  'Social' => [['facebook', 'Facebook', 'url'], ['instagram', 'Instagram', 'url'], ['tiktok', 'TikTok', 'url'], ['youtube', 'YouTube', 'url'], ['linkedin', 'LinkedIn', 'url']],
  'Colors' => [['color_primary', 'Accent (gold)', 'color'], ['color_secondary', 'Surface', 'color'], ['color_bg', 'Background', 'color']]]; $errs = [];
  if ($post) { guard(); $save = []; foreach ($groups as $fs) foreach ($fs as $f) { $v = trim(mb_substr((string)($_POST[$f[0]] ?? ''), 0, 600)); $t = $f[2] ?? 'text';
      if ($t === 'color' && !preg_match('/^#[0-9a-fA-F]{6}$/', $v)) $errs[] = $f[1] . ' must be a valid color.'; if ($t === 'url' && $v !== '' && !preg_match('#^https?://\S+$#i', $v)) $errs[] = $f[1] . ' must start with http:// or https://'; if ($t === 'email' && $v !== '' && !filter_var($v, FILTER_VALIDATE_EMAIL)) $errs[] = 'Enter a valid email address.';
      if (in_array($f[0], ['company', 'brand', 'cta_text'], true) && $v === '') $errs[] = $f[1] . ' is required.'; $save[$f[0]] = $v; }
    foreach (['logo', 'hero_image'] as $im) $save[$im] = take_image($im, $S[$im], $errs);
    if (!$errs) { foreach ($save as $k => $v) q('INSERT INTO settings(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v', [$k, $v]); flash('Settings saved.'); redirect('/admin/settings'); } $S = array_merge($S, $save); }
  $b = '<form method="post" enctype="multipart/form-data" class="stack gap8" style="max-width:900px">' . csrf(); foreach ($errs as $e) $b .= '<p role="alert" class="form-error">' . h($e) . '</p>';
  $b .= '<fieldset class="panel stack gap4"><legend class="h3">Images</legend><p class="small muted">Logo replaces the header mark and the logo on the homepage. The hero photo becomes the full-width homepage background.</p>' . img_field('logo', 'Logo', $S['logo']) . img_field('hero_image', 'Homepage hero photo', $S['hero_image']) . '</fieldset>';
  foreach ($groups as $g => $fs) { $b .= '<fieldset class="panel stack gap4"><legend class="h3">' . h($g) . '</legend><div class="form-grid">'; foreach ($fs as $f) { $t = $f[2] ?? 'text'; $b .= $t === 'area' ? '<div class="wide">' . area($f[0], $f[1], $S[$f[0]], 3) . '</div>' : inp($f[0], $f[1], $S[$f[0]], $t); } $b .= '</div></fieldset>'; }
  adm('Site settings', $b . '<div><button class="btn btn-primary" type="submit">Save settings</button></div></form>'); return; }

$cnt = function ($t, $w = '1') { return (int)q("SELECT COUNT(*) FROM $t WHERE $w")->fetchColumn(); };
adm('Dashboard', '<div class="result-grid"><div class="stat"><span class="caption">New inquiries</span><strong>' . $cnt('inquiries', "status='new'") . '</strong></div><div class="stat"><span class="caption">Published projects</span><strong>' . $cnt('projects', 'published=1') . '</strong></div><div class="stat"><span class="caption">Published services</span><strong>' . $cnt('services', 'published=1') . '</strong></div><div class="stat"><span class="caption">Calculator presets</span><strong>' . $cnt('presets', 'active=1') . '</strong></div></div><p class="lead">Start with <a href="/admin/settings">Site settings</a>: logo, hero photo, contact details and homepage text. Then add services and projects.</p>');
